void text(HDC dc,int x,int y,int w,int h,const std::wstring& s,COLORREF color=TEXT,int size=11,bool bold=false,UINT flags=DT_LEFT|DT_VCENTER|DT_SINGLELINE){SetBkMode(dc,TRANSPARENT);SetTextColor(dc,color);HFONT f=CreateFontW(-size,0,0,0,bold?FW_BOLD:FW_NORMAL,FALSE,FALSE,FALSE,DEFAULT_CHARSET,OUT_DEFAULT_PRECIS,CLIP_DEFAULT_PRECIS,CLEARTYPE_QUALITY,DEFAULT_PITCH|FF_DONTCARE,L"Segoe UI");auto old=SelectObject(dc,f);RECT r{x,y,x+w,y+h};DrawTextW(dc,s.c_str(),static_cast<int>(s.size()),&r,flags);SelectObject(dc,old);DeleteObject(f);}
void fill(HDC dc,const RECT& r,COLORREF color,int radius=10){HBRUSH b=CreateSolidBrush(color);HPEN p=CreatePen(PS_SOLID,1,BORDER);auto ob=SelectObject(dc,b);auto op=SelectObject(dc,p);RoundRect(dc,r.left,r.top,r.right,r.bottom,radius,radius);SelectObject(dc,ob);SelectObject(dc,op);DeleteObject(b);DeleteObject(p);}
