 int x=246,w=W-x-28;text(dc,x,22,w,15,L"NORTHSTAR POS  /  WINDOWS DESKTOP",MUTED,8,true);text(dc,x,43,w,36,page==0?L"Good morning, operator":page==1?L"Inventory overview":L"Sales history",TEXT,24,true);button(dc,W-150,31,120,31,L"UI PREVIEW",PANEL2,AMBER);
