  int top=201,leftW=(w-14)*60/100,rightX=x+leftW+14,rightW=w-leftW-14;RECT cat{x,top,x+leftW,H-151};fill(dc,cat,PANEL);text(dc,x+16,top+12,leftW-32,23,L"Start a sale",TEXT,13,true);text(dc,x+16,top+38,leftW-32,16,L"Select a sample product to add it to the cart.",MUTED,8);
